    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});

    // For function-valued definitions, recompile the schema to validate against the current one
    const resolved = this.resolveDefinition(tool.definitionSource);
    const validateInput =
      typeof tool.definitionSource === 'function' ? compileSchema(resolved.name, resolved.inputSchema) : tool.validateInput;

    const isValid = validateInput(input);
    if (!isValid) {
      const errors = validateInput.errors || [];
      const errorMessages = errors
        .map(error => {
          const path = error.instancePath || '/';
          const constraint = getConstraintDescription(error);
          return `${path}: ${constraint}`;
        })
        .join('; ');
      return {result: errorMessages};
    }

    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

const CONSTRAINT_DESCRIPTIONS: Record<
  string,
  (keyword: string, params: Record<string, unknown>) => string
> = {
  required: (keyword, params) => `${keyword}: missing required property "${params.missingProperty}"`,
  type: (keyword, params) => `${keyword}: expected type ${params.type}`,
  enum: (keyword, params) => `${keyword}: must be one of the allowed values`,
};

function getConstraintDescription(error: {keyword?: string; params?: Record<string, unknown>}): string {
  const keyword = error.keyword || 'validation';
  const params = (error.params || {}) as Record<string, unknown>;
  const describer = CONSTRAINT_DESCRIPTIONS[keyword];
  return describer ? describer(keyword, params) : `${keyword} validation failed`;
}

